/* KEFE background effect — CRT Computer Desktop. Converted from the supplied standalone effect. */
(function(){
  'use strict';
  window.kefeEffects=window.kefeEffects||{};
  var image=new Image(),loaded=false;
  image.onload=function(){loaded=true;window.dispatchEvent(new Event('kefe-effects-ready'));};
  image.src="data:image/jpeg;base64,";
  var state={secPerLine:3,crt:1},STORE='kefe.crtdesktop.v1';
  try{var saved=JSON.parse(localStorage.getItem(STORE)||'{}');if(Number.isFinite(Number(saved.secPerLine)))state.secPerLine=Number(saved.secPerLine);if(Number.isFinite(Number(saved.crt)))state.crt=Number(saved.crt);}catch(e){}
  function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){}}
  function cover(ctx,img,w,h){var s=Math.max(w/img.width,h/img.height),dw=img.width*s,dh=img.height*s;ctx.drawImage(img,(w-dw)/2,(h-dh)/2,dw,dh);}
  function rr(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}
  function render(ctx,w,h,style,lines,time){
    ctx.save();
    if(loaded)cover(ctx,image,w,h);else{ctx.fillStyle='#0d0f0e';ctx.fillRect(0,0,w,h);}
    var sx=w*.154,sy=h*.179,sw=w*.683,sh=h*.517,r=Math.min(sw,sh)*.07,I=Math.max(0,Math.min(1,state.crt));
    ctx.save();rr(ctx,sx,sy,sw,sh,r);ctx.clip();
    ctx.fillStyle='#050806';ctx.fillRect(sx,sy,sw,sh);
    ctx.filter='blur('+(.35*I).toFixed(2)+'px) contrast('+(1+.15*I).toFixed(2)+') saturate('+(1+.2*I).toFixed(2)+')';
    var g=ctx.createLinearGradient(sx,sy,sx+sw,sy+sh);g.addColorStop(0,'rgba(30,215,96,'+(.16*I)+')');g.addColorStop(1,'rgba(5,8,6,0)');ctx.fillStyle=g;ctx.fillRect(sx,sy,sw,sh);ctx.filter='none';
    ctx.globalAlpha=.35*I;ctx.strokeStyle='#1ed760';ctx.lineWidth=Math.max(1,w/900);
    var step=Math.max(12,sw/24);for(var x=sx-sw;x<sx+sw*2;x+=step){ctx.beginPath();ctx.moveTo(x,sy);ctx.lineTo(x+sh*.65,sy+sh);ctx.stroke();}
    for(var y=sy;y<sy+sh;y+=Math.max(3,sh/90)){ctx.globalAlpha=.12*I;ctx.fillStyle='#e8e6da';ctx.fillRect(sx,y,sw,Math.max(1,sh/500));}
    ctx.globalAlpha=.35*I;var glow=ctx.createRadialGradient(sx+sw*.5,sy+sh*.9,0,sx+sw*.5,sy+sh*.9,sw*.75);glow.addColorStop(0,'#1ed76066');glow.addColorStop(1,'transparent');ctx.fillStyle=glow;ctx.fillRect(sx,sy,sw,sh);
    ctx.globalAlpha=.35*I;var scanY=sy+((time/Math.max(.25,state.secPerLine))*sh*.35)%sh;ctx.fillStyle='#fff';ctx.fillRect(sx,scanY,sw,Math.max(1,sh*.012));
    ctx.globalAlpha=.25*I;var flick=.5+.25*Math.sin(time*47.3)+.15*Math.sin(time*13.1+1);ctx.fillStyle='#000';ctx.fillRect(sx,sy,sw,sh*.035*Math.max(0,flick));
    ctx.globalAlpha=1;
    var active=window.kefeEffectUtils?.activeLine(lines,time), line=active?.line, lp=active?window.kefeEffectUtils.lineProgress(active.line,time):null;
    if(line&&lp&&lp.opacity>.01){
      var lyric=String(line.text||'').trim();
      if(lyric){
        var reveal=Math.max(.08,Math.min(1,(time-Number(line.time||0))/Math.max(.12,state.secPerLine*.18)));
        var chars=Math.max(1,Math.ceil(lyric.length*reveal));
        lyric=lyric.slice(0,chars);
        ctx.save();
        rr(ctx,sx,sy,sw,sh,r);
        ctx.clip();
        ctx.textAlign='center';
        ctx.textBaseline='middle';
        ctx.font=Math.max(20,Math.min(sw*.09,sh*.18))+'px "VT323","Courier New",monospace';
        ctx.globalAlpha=lp.opacity*Math.min(1,I+.35);
        ctx.fillStyle='#f1efe2';
        ctx.shadowColor='#1ed760';
        ctx.shadowBlur=Math.max(4,sw*.018)*I;
        var maxWidth=sw*.84;
        while(ctx.measureText(lyric).width>maxWidth){
          var match=ctx.font.match(/([0-9.]+)px/);
          var fs=Math.max(20,parseFloat(match?.[1]||20)-2);
          if(fs<=20){ctx.font='20px "VT323","Courier New",monospace';break;}
          ctx.font=fs+'px "VT323","Courier New",monospace';
        }
        ctx.fillText(lyric,sx+sw/2,sy+sh/2);
        ctx.globalAlpha*=.6;
        ctx.shadowBlur=0;
        ctx.fillStyle='#ff2a4a';
        ctx.fillText(lyric,sx+sw/2-1.5,sy+sh/2);
        ctx.fillStyle='#21e6ff';
        ctx.fillText(lyric,sx+sw/2+1.5,sy+sh/2);
        ctx.restore();
      }
    }
    ctx.restore();ctx.restore();
  }
  render.idle=true;window.kefeEffects.crtdesktop=render;
  function buildPanel(){
    var host=document.querySelector('[data-panel-view="effects"] .kefe-form');if(!host||document.getElementById('crtDesktopControls'))return null;
    var wrap=document.createElement('div');wrap.id='crtDesktopControls';wrap.className='crt-controls';
    var group=document.createElement('div');group.className='crt-group';var hd=document.createElement('h3');hd.textContent='CRT Computer Desktop';group.appendChild(hd);
    function row(label,key,min,max,step,suffix){var r=document.createElement('label');r.className='crt-row';var s=document.createElement('span');s.textContent=label;r.appendChild(s);var input=document.createElement('input');input.type='range';input.className='crt-range';input.min=min;input.max=max;input.step=step;input.value=state[key];var out=document.createElement('output');out.textContent=state[key]+suffix;input.addEventListener('input',function(){state[key]=Number(input.value);out.textContent=input.value+suffix;save();window.dispatchEvent(new Event('kefe-effects-ready'));});r.appendChild(input);r.appendChild(out);group.appendChild(r);}
    row('Sec/line','secPerLine',1,8,.5,'s');row('CRT','crt',0,1,.1,'');wrap.appendChild(group);host.appendChild(wrap);return wrap;
  }
  var panel=buildPanel(),sel=document.getElementById('lyricEffect');
  function sync(){if(panel)panel.hidden=!(sel&&sel.value==='crtdesktop');}
  if(sel)sel.addEventListener('change',sync);sync();
})();
